    const notice = root.createDiv({ cls: "svn-confirmation-notice is-warning" });
    const noticeIcon = notice.createSpan({ attr: { "aria-hidden": "true" } });
    (0, import_obsidian2.setIcon)(noticeIcon, "triangle-alert");
