    const actions = root.createDiv({ cls: "svn-confirmation-actions" });
    const cancel = actions.createEl("button", { text: "\u53D6\u6D88", cls: "svn-button is-secondary", attr: { type: "button", title: "\u53D6\u6D88\u5F53\u524D\u66F4\u65B0", "aria-label": "\u53D6\u6D88\u5F53\u524D\u66F4\u65B0" } });
    cancel.addEventListener("click", () => this.close());
